"""Read-only Linux checks for the standalone course gomoku program."""
from pathlib import Path
import argparse, array, fcntl, json, os, stat, struct, subprocess

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project',required=True);parser.add_argument('--touch')
    args=parser.parse_args();project=Path(args.project).resolve(strict=True)
    errors=[];report={'project':str(project),'checksAreReadOnly':True}
    binary=project/'out/lab6_gomoku'
    if not binary.is_file() or not os.access(binary,os.X_OK):errors.append('Build out/lab6_gomoku first.')
    if not (project/'out/font.ttc').is_file():errors.append('Missing course out/font.ttc.')
    try:
        if not stat.S_ISCHR(os.stat('/dev/fb0').st_mode):raise OSError('fb0 is not a character device')
        fd=os.open('/dev/fb0',os.O_RDWR)
        try:
            var=array.array('I',[0]*40);fix=bytearray(80)
            fcntl.ioctl(fd,0x4600,var,True);fcntl.ioctl(fd,0x4602,fix,True)
        finally:os.close(fd)
        stride=struct.unpack_from('I',fix,48)[0];memory=struct.unpack_from('I',fix,24)[0]
        report['framebuffer']={'width':var[0],'height':var[1],'bpp':var[6],'lineBytes':stride,'memoryBytes':memory}
        if tuple(var[i] for i in (0,1,6,8,9,11,12,14,15))!=(1024,600,32,16,8,8,8,0,8) or stride<4096 or memory<stride*600:
            errors.append('Expected course 1024x600 32-bit RGB framebuffer; check fbset mode.')
    except OSError as error:errors.append(f'Framebuffer: {error}')
    devices=[]
    for path in ([Path(args.touch)] if args.touch else sorted(Path('/dev/input').glob('event*'))):
        try:
            fd=os.open(path,os.O_RDONLY|os.O_NONBLOCK)
            axes={}
            try:
                for name,code in (('slot',0x2f),('x',0x35),('y',0x36)):
                    values=array.array('i',[0]*6)
                    fcntl.ioctl(fd,(2<<30)|(24<<16)|(ord('E')<<8)|(0x40+code),values,True)
                    axes[name]=[values[1],values[2]]
            finally:os.close(fd)
            if axes['slot'][0]!=0 or axes['x'][1]<=axes['x'][0] or axes['y'][1]<=axes['y'][0]:continue
            devices.append({'path':str(path),'axes':axes})
        except OSError:continue
    report['touchscreens']=devices
    if not devices:errors.append('No protocol-B touch device available; check the USB touch cable.')
    if len(devices)>1 and not args.touch:errors.append('Choose one device with --touch /dev/input/eventN.')
    manager=subprocess.run(['systemctl','is-active','display-manager'],capture_output=True,text=True)
    report['displayManager']=manager.stdout.strip()
    if manager.returncode==0:errors.append('Stop the board display-manager before running framebuffer programs.')
    active=[]
    for entry in Path('/proc').iterdir():
        if not entry.name.isdigit():continue
        try:
            name=(entry/'comm').read_text().strip()
            executable=os.readlink(entry/'exe')
            if executable.endswith(' (deleted)'):executable=executable[:-10]
            if name in ('lab2','lab3','lab4','lab5_bt','lab6_gomoku','test') and Path(executable).parent==project/'out':
                active.append({'pid':int(entry.name),'name':name})
        except OSError:continue
    report['otherCoursePrograms']=active
    if active:errors.append('Stop the listed existing course programs before sharing the framebuffer/touch device.')
    report['problems']=errors
    print(json.dumps(report,ensure_ascii=False,indent=2))
    return bool(errors)

if __name__=='__main__':raise SystemExit(main())

/* HOST SIMULATION ONLY: decoded assets and glyph masks are produced by Pillow.
 * The deployment package uses the course's actual libjpeg/libpng/FreeType code. */
#include "../common/common.h"
#include "image-memory-under-test.c"

void font_init(char *path) { (void)path; }
static fb_image *load_pixels(const char *name)
{
    char path[256];snprintf(path,sizeof(path),"build/assets/%s.bgra",name);
    FILE *f=fopen(path,"rb");if(!f) return NULL;
    int32_t header[3];if(fread(header,sizeof(header),1,f)!=1) {fclose(f);return NULL;}
    fb_image *img=fb_new_image(header[2],header[0],header[1],0);
    if(img && fread(img->content,(size_t)img->line_byte*img->pixel_h,1,f)!=1) {fb_free_image(img);img=NULL;}
    fclose(f);return img;
}
fb_image *fb_read_jpeg_image(char *path) {(void)path;return load_pixels("test.jpg");}
fb_image *fb_read_png_image(char *path) {(void)path;return load_pixels("test.png");}
fb_image *fb_read_font_image(const char *text,int size,fb_font_info *info)
{
    const unsigned char *p=(const unsigned char *)text;
    unsigned code;int bytes;
    if(p[0]<0x80) {code=p[0];bytes=1;}
    else if(p[0]<0xe0) {code=((p[0]&31)<<6)|(p[1]&63);bytes=2;}
    else if(p[0]<0xf0) {code=((p[0]&15)<<12)|((p[1]&63)<<6)|(p[2]&63);bytes=3;}
    else {code=((p[0]&7)<<18)|((p[1]&63)<<12)|((p[2]&63)<<6)|(p[3]&63);bytes=4;}
    char path[256];snprintf(path,sizeof(path),"build/assets/glyph-%x-%d.bin",code,size);
    FILE *f=fopen(path,"rb");if(!f) {fprintf(stderr,"Missing host glyph: %s\n",path);return NULL;}
    int32_t h[5];if(fread(h,sizeof(h),1,f)!=1) {fclose(f);return NULL;}
    fb_image *img=fb_new_image(FB_COLOR_ALPHA_8,h[0],h[1],h[0]);
    if(img && h[0]*h[1]>0 && fread(img->content,(size_t)h[0]*h[1],1,f)!=1) {fb_free_image(img);img=NULL;}
    fclose(f);
    if(info) *info=(fb_font_info){bytes,h[4],h[2],-h[3]};
    return img;
}

