static int oracle_winner(const gm_game *g)
{
    const int dirs[][2]={{0,1},{1,0},{1,1},{1,-1}};
    for(int r=0;r<GM_SIZE;++r) for(int c=0;c<GM_SIZE;++c)
        for(int d=0;d<4;++d) {
            int side=g->cells[r][c],ok=side!=0;
            for(int k=1;k<5 && ok;++k) {
                int rr=r+k*dirs[d][0],cc=c+k*dirs[d][1];
                if(rr<0 || rr>=GM_SIZE || cc<0 || cc>=GM_SIZE || g->cells[rr][cc]!=side) ok=0;
            }
            if(ok) return side;
        }
    return 0;
}
static void verify_state(const gm_game *g)
{
    int black=0,white=0;
    uint8_t visited[GM_SIZE][GM_SIZE]={{0}};
    for(int r=0;r<GM_SIZE;++r) for(int c=0;c<GM_SIZE;++c) {
        CHECK(g->cells[r][c]<=GM_WHITE);
        black+=g->cells[r][c]==GM_BLACK;white+=g->cells[r][c]==GM_WHITE;
    }
    CHECK(black+white==g->count);CHECK(black==white || black==white+1);
    CHECK(g->next==(g->count%2 ? GM_WHITE : GM_BLACK));
    for(int i=0;i<g->count;++i) {
        gm_move m=g->moves[i];CHECK(m.row>=0 && m.row<GM_SIZE && m.col>=0 && m.col<GM_SIZE);
        CHECK(!visited[m.row][m.col]);visited[m.row][m.col]=1;
        CHECK(g->cells[m.row][m.col]==(i%2 ? GM_WHITE : GM_BLACK));
    }
    int winner=oracle_winner(g);
    CHECK(g->result==(winner ? winner : g->count==GM_CAPACITY ? GM_DRAW : GM_EMPTY));
}
static void rule_tests(void)
{
    const int dirs[][2]={{0,1},{1,0},{1,1},{1,-1}};
    for(int d=0;d<4;++d) {
        gm_game g;gm_init(&g);int col=d==3?14:0;
        for(int k=0;k<5;++k) {
            CHECK(gm_play(&g,k*dirs[d][0],col+k*dirs[d][1]));
            if(k<4) CHECK(gm_play(&g,14,k*2));
        }
        CHECK(g.result==GM_BLACK);verify_state(&g);
        gm_move a,b;CHECK(gm_win_line(&g,&a,&b));
        CHECK(a.row==0 && a.col==col);CHECK(b.row==4*dirs[d][0] && b.col==col+4*dirs[d][1]);
        gm_game snapshot=g;CHECK(!gm_play(&g,8,8));CHECK(!memcmp(&snapshot,&g,sizeof(g)));
        CHECK(gm_undo(&g,1)==1);CHECK(g.result==GM_EMPTY && g.next==GM_BLACK);
        CHECK(gm_play(&g,4*dirs[d][0],col+4*dirs[d][1]));CHECK(g.result==GM_BLACK);
        CHECK(gm_undo(&g,1000)==9);CHECK(g.count==0 && g.next==GM_BLACK);
    }
    gm_game g;gm_init(&g);const int cols[]={1,2,3,5,6,4};
    for(int i=0;i<6;++i) { CHECK(gm_play(&g,7,cols[i]));if(i<5) CHECK(gm_play(&g,14,2*i)); }
    CHECK(g.result==GM_BLACK);gm_move a,b;CHECK(gm_win_line(&g,&a,&b));CHECK(b.col-a.col==5);
    gm_init(&g);gm_game snapshot=g;
    CHECK(!gm_play(&g,-1,0));CHECK(!gm_play(&g,GM_SIZE,0));CHECK(!gm_play(&g,0,INT_MAX));
    CHECK(!gm_play(&g,INT_MIN,0));CHECK(!memcmp(&snapshot,&g,sizeof(g)));
    CHECK(!gm_would_win(&g,0,0,0));CHECK(gm_undo(&g,-1)==0);
    CHECK(gm_play(&g,0,0));snapshot=g;CHECK(!gm_play(&g,0,0));CHECK(!memcmp(&snapshot,&g,sizeof(g)));
    /* Full-board pattern has no horizontal, vertical or diagonal run of five. */
    gm_init(&g);
    for(int r=0;r<GM_SIZE;++r) for(int c=0;c<GM_SIZE;++c)
        g.cells[r][c]=(uint8_t)((r+2*c)%4<2 ? GM_BLACK : GM_WHITE);
    CHECK(!oracle_winner(&g));g.cells[0][0]=0;g.count=GM_CAPACITY-1;g.next=GM_BLACK;
    CHECK(gm_play(&g,0,0));CHECK(g.result==GM_DRAW);CHECK(!gm_win_line(&g,&a,&b));
    CHECK(!gm_play(&g,0,0));CHECK(gm_undo(&g,1)==1 && !g.result);
    gm_init(&g);
    for(int i=0;i<5;++i) { CHECK(gm_play(&g,0,2*i));CHECK(gm_play(&g,14,i)); }
    CHECK(g.result==GM_WHITE);verify_state(&g);
    CHECK(gm_undo(&g,1)==1 && g.next==GM_WHITE && !g.result);
    CHECK(gm_play(&g,14,4) && g.result==GM_WHITE);
    for(int match=0;match<80;++match) {
        gm_init(&g);
        for(int turn=0;turn<160 && !g.result;++turn) {
            int r=(int)(random_value()%GM_SIZE),c=(int)(random_value()%GM_SIZE);
            if(gm_legal(&g,r,c)) CHECK(gm_play(&g,r,c));
            if(turn%17==16) gm_undo(&g,1+(int)(random_value()%3));
            verify_state(&g);
        }
    }
}
static gm_move choose(const gm_game *g)
{
    gm_ai ai;gm_game snapshot=*g;gm_ai_begin(&ai,g);
    CHECK(ai.count<=GM_AI_CANDIDATES);
    int calls=0;while(!gm_ai_step(&ai)) CHECK(++calls<=GM_AI_CANDIDATES);
    CHECK(!memcmp(g,&snapshot,sizeof(*g)));
    if(!g->result && g->count<GM_CAPACITY) CHECK(gm_legal(g,ai.best.row,ai.best.col));
    else CHECK(ai.best.row==-1 && ai.best.col==-1);
    return ai.best;
}
static void ai_tests(void)
{
    gm_game g;gm_init(&g);gm_move m=choose(&g);CHECK(m.row==7 && m.col==7);
    for(int side=GM_BLACK;side<=GM_WHITE;++side) {
        gm_init(&g);g.next=side;g.count=9;
        for(int c=3;c<7;++c) {g.cells[5][c]=(uint8_t)side;g.cells[9][c]=(uint8_t)(3-side);}
        g.cells[5][2]=(uint8_t)(3-side);m=choose(&g);
        CHECK(gm_would_win(&g,m.row,m.col,side));
        gm_init(&g);g.next=side;g.count=5;
        for(int c=3;c<7;++c) g.cells[5][c]=(uint8_t)(3-side);
        g.cells[5][2]=(uint8_t)side;m=choose(&g);CHECK(m.row==5 && m.col==7);
        gm_init(&g);g.next=side;g.count=4;
        g.cells[7][3]=g.cells[7][4]=g.cells[7][6]=g.cells[7][7]=(uint8_t)side;
        m=choose(&g);CHECK(m.row==7 && m.col==5);
    }
    for(int match=0;match<3;++match) {
        gm_init(&g);
        while(!g.result && g.count<80) {
            if(g.count==0 && match) CHECK(gm_play(&g,7,7-match));
            m=choose(&g);CHECK(gm_play(&g,m.row,m.col));verify_state(&g);
        }
        if(g.result) { m=choose(&g);CHECK(m.row==-1); }
    }
}
